   3 import { useLocalization } from '@/context/LocalizationContext';
   4 import React, { useEffect } from 'react';
   5 
   6 export default function LanguageDirectionManager({ children }: { children: React.ReactNode }) {
   7   const { locale } = useLocalization();
   8 
   9   useEffect(() => {
  10     document.documentElement.lang = locale;
  11     document.documentElement.dir = locale === 'ar' ? 'rtl' : 'ltr';
  12 
  13     if (locale === 'ar') {
  14       document.body.classList.add('font-arabic');
  15     } else {
  16       document.body.classList.remove('font-arabic');
  17     }
  18   }, [locale]);
  19 
  20   return <>{children}</>;
  21 }
